package com.sebastian.spring.mas.aliado.aliado.modules.servicios.application.service;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.application.dto.*;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.application.port.*;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.application.exception.ServicioOperacionException;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.domain.exception.TransicionServicioInvalidaException;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.domain.model.*;
import com.sebastian.spring.mas.aliado.aliado.modules.servicios.domain.repository.ServicioRepository;
import com.sebastian.spring.mas.aliado.aliado.modules.propuestas.domain.model.*;
import com.sebastian.spring.mas.aliado.aliado.modules.solicitudes.domain.model.*;

import java.util.*;
import java.time.OffsetDateTime;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ServicioUseCasesTest {
 private final UUID cliente=UUID.randomUUID(),prestador=UUID.randomUUID(),solId=UUID.randomUUID(),propuestaId=UUID.randomUUID();
 private final Repo repo=new Repo();private final Propuestas propuestas=new Propuestas();private final Solicitudes solicitudes=new Solicitudes();private final List<Object> eventos=new ArrayList<>();
 private final OffsetDateTime ahora=OffsetDateTime.now();
 private ServicioContratado servicio(EstadoServicio e,boolean canal){return new ServicioContratado(UUID.randomUUID(),solId,propuestaId,cliente,prestador,e,canal,ahora,3,List.of(),List.of());}
 private Propuesta propuesta(EstadoPropuesta e){return new Propuesta(propuestaId,solId,prestador,"Lunes",null,e,ahora,ahora,0);}
 private Solicitud solicitud(UUID dueno,EstadoSolicitud e){return new Solicitud(solId,dueno,UUID.randomUUID(),UUID.randomUUID(),"Trabajo",Urgencia.MEDIA,e,ahora,ahora,0,List.of(),List.of());}
 private AceptarPropuestaService aceptar(){return new AceptarPropuestaService(repo,propuestas,solicitudes,eventos::add,new RegistrarServicioContratadoService(repo,new HabilitarComunicacionServicioService()),new CerrarPropuestasNoSeleccionadasService(propuestas));}
 private void preparar(){propuestas.datos.put(propuestaId,propuesta(EstadoPropuesta.ACTIVA));solicitudes.actual=solicitud(cliente,EstadoSolicitud.PUBLICADA);}
 private AccionServicioCommand accion(ServicioContratado s,UUID actor){return new AccionServicioCommand(s.id(),actor);}
 @Test void aceptarRegistraRelacionesHistorialCanalYCierraResto(){preparar();UUID otra=UUID.randomUUID();propuestas.datos.put(otra,new Propuesta(otra,solId,UUID.randomUUID(),"Martes",null,EstadoPropuesta.ACTIVA,ahora,ahora,0));var r=aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente));var s=repo.porId(r.id()).orElseThrow();assertEquals(cliente,s.clienteId());assertEquals(prestador,s.prestadorId());assertTrue(s.comunicacionHabilitada());assertEquals(EstadoServicio.CONTRATADO,s.estado());assertEquals(1,s.historial().size());assertEquals(cliente,s.historial().get(0).actorId());assertEquals(EstadoPropuesta.ACEPTADA,propuestas.datos.get(propuestaId).estado());assertEquals(EstadoPropuesta.CERRADA,propuestas.datos.get(otra).estado());assertEquals(EstadoSolicitud.CONTRATADA,solicitudes.actual.estado());assertEquals(1,eventos.size());}
 @Test void aceptarAjenaNoModifica(){preparar();var ex=assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,UUID.randomUUID())));assertEquals(ServicioOperacionException.Tipo.NO_AUTORIZADO,ex.tipo());assertTrue(repo.datos.isEmpty());assertTrue(eventos.isEmpty());}
 @Test void propuestaInexistenteRechazada(){assertEquals("PROPUESTA_NO_ENCONTRADA",assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente))).codigo());}
 @Test void solicitudInexistenteRechazada(){propuestas.datos.put(propuestaId,propuesta(EstadoPropuesta.ACTIVA));assertEquals("SOLICITUD_NO_ENCONTRADA",assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente))).codigo());}
 @Test void propuestaInactivaNoRegistra(){preparar();for(var e:List.of(EstadoPropuesta.RETIRADA,EstadoPropuesta.CERRADA,EstadoPropuesta.ACEPTADA)){propuestas.datos.put(propuestaId,propuesta(e));assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente)));}assertTrue(repo.datos.isEmpty());}
 @Test void solicitudNoPublicadaNoRegistra(){preparar();for(var e:List.of(EstadoSolicitud.BORRADOR,EstadoSolicitud.CONTRATADA,EstadoSolicitud.CANCELADA)){solicitudes.actual=solicitud(cliente,e);assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente)));}assertTrue(repo.datos.isEmpty());}
 @Test void servicioExistenteBloqueaSegundaContratacion(){preparar();repo.guardar(servicio(EstadoServicio.CONTRATADO,true));assertEquals("SERVICIO_YA_CONTRATADO",assertThrows(ServicioOperacionException.class,()->aceptar().ejecutar(new AceptarPropuestaCommand(propuestaId,cliente))).codigo());assertEquals(1,repo.datos.size());assertTrue(eventos.isEmpty());}
 @Test void listadoPropioSoloActivas(){preparar();var u=new ListarPropuestasRecibidasService(solicitudes,propuestas);assertEquals(1,u.ejecutar(new ListadoPropuestasQuery(solId,cliente)).size());propuestas.datos.clear();assertTrue(u.ejecutar(new ListadoPropuestasQuery(solId,cliente)).isEmpty());}
 @Test void listadoAjenoEInexistenteMismoError(){preparar();var u=new ListarPropuestasRecibidasService(solicitudes,propuestas);var ajena=assertThrows(ServicioOperacionException.class,()->u.ejecutar(new ListadoPropuestasQuery(solId,UUID.randomUUID())));solicitudes.actual=null;var ausente=assertThrows(ServicioOperacionException.class,()->u.ejecutar(new ListadoPropuestasQuery(solId,cliente)));assertEquals(ajena.codigo(),ausente.codigo());}
 @Test void detalleIgualParaAmbasPartes(){preparar();var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));var u=new ConsultarServicioService(repo,solicitudes,propuestas);assertEquals(u.ejecutar(accion(s,cliente)),u.ejecutar(accion(s,prestador)));assertEquals("Trabajo",u.ejecutar(accion(s,cliente)).solicitud().descripcion());}
 @Test void detalleAjenoEInexistenteMismoError(){preparar();var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));var u=new ConsultarServicioService(repo,solicitudes,propuestas);var ajena=assertThrows(ServicioOperacionException.class,()->u.ejecutar(accion(s,UUID.randomUUID())));var ausente=assertThrows(ServicioOperacionException.class,()->u.ejecutar(new AccionServicioCommand(UUID.randomUUID(),cliente)));assertEquals(ajena.codigo(),ausente.codigo());}
 @Test void cicloCompletoRegistraCadaActorYEvento(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));new MarcarServicioEnEjecucionService(repo,eventos::add).ejecutar(accion(s,prestador));new MarcarServicioTerminadoService(repo,eventos::add).ejecutar(accion(s,prestador));new ConfirmarFinalizacionServicioService(repo,eventos::add).ejecutar(accion(s,cliente));var actual=repo.porId(s.id()).orElseThrow();assertEquals(EstadoServicio.FINALIZADO,actual.estado());assertEquals(List.of(prestador,prestador,cliente),actual.historial().stream().map(HistorialEstadoServicio::actorId).toList());assertEquals(3,eventos.size());assertEquals(3,actual.version());}
 @Test void clienteNoPuedeIniciarNiTerminar(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));assertThrows(ServicioOperacionException.class,()->new MarcarServicioEnEjecucionService(repo,eventos::add).ejecutar(accion(s,cliente)));assertThrows(ServicioOperacionException.class,()->new MarcarServicioTerminadoService(repo,eventos::add).ejecutar(accion(s,cliente)));assertEquals(s,repo.porId(s.id()).orElseThrow());assertTrue(eventos.isEmpty());}
 @Test void prestadorNoPuedeConfirmar(){var s=repo.guardar(servicio(EstadoServicio.TERMINADO,true));assertThrows(ServicioOperacionException.class,()->new ConfirmarFinalizacionServicioService(repo,eventos::add).ejecutar(accion(s,prestador)));assertTrue(eventos.isEmpty());}
 @Test void terceroNoPuedeCancelar(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));assertThrows(ServicioOperacionException.class,()->new CancelarServicioService(repo,eventos::add).ejecutar(accion(s,UUID.randomUUID())));assertTrue(eventos.isEmpty());}
 @Test void cualquieraDeLasPartesPuedeCancelarAntesDeFinalizar(){for(var actor:List.of(cliente,prestador)){var s=repo.guardar(servicio(EstadoServicio.TERMINADO,true));assertEquals("CANCELADO",new CancelarServicioService(repo,eventos::add).ejecutar(accion(s,actor)).estado());}}
 @Test void finalizarYCancelarSonTerminales(){for(var e:List.of(EstadoServicio.FINALIZADO,EstadoServicio.CANCELADO)){var s=repo.guardar(servicio(e,true));assertThrows(TransicionServicioInvalidaException.class,()->new CancelarServicioService(repo,eventos::add).ejecutar(accion(s,cliente)));assertEquals(s,repo.porId(s.id()).orElseThrow());}}
 @Test void terminarSinEjecucionNoGuarda(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));assertThrows(TransicionServicioInvalidaException.class,()->new MarcarServicioTerminadoService(repo,eventos::add).ejecutar(accion(s,prestador)));assertTrue(eventos.isEmpty());}
 @Test void historialRestringidoAParticipantes(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));var u=new ConsultarHistorialServicioService(repo);assertTrue(u.ejecutar(accion(s,cliente)).isEmpty());assertThrows(ServicioOperacionException.class,()->u.ejecutar(accion(s,UUID.randomUUID())));}
 @Test void mensajeSeGuardaYAmbasPartesPuedenLeer(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));var m=new EnviarMensajeServicioService(repo).ejecutar(new EnviarMensajeServicioCommand(s.id(),cliente," Hola "));assertEquals("Hola",m.contenido());assertEquals(cliente,m.remitenteId());var lectura=new ConsultarMensajesServicioService(repo);assertEquals(List.of(m),lectura.ejecutar(accion(s,cliente)));assertEquals(List.of(m),lectura.ejecutar(accion(s,prestador)));}
 @Test void mensajeAjenoNoGuarda(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));assertThrows(ServicioOperacionException.class,()->new EnviarMensajeServicioService(repo).ejecutar(new EnviarMensajeServicioCommand(s.id(),UUID.randomUUID(),"Hola")));assertTrue(repo.porId(s.id()).orElseThrow().mensajes().isEmpty());}
 @Test void canalNoHabilitadoRechazaEnvioYLectura(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,false));assertThrows(ServicioOperacionException.class,()->new EnviarMensajeServicioService(repo).ejecutar(new EnviarMensajeServicioCommand(s.id(),cliente,"Hola")));assertThrows(ServicioOperacionException.class,()->new ConsultarMensajesServicioService(repo).ejecutar(accion(s,prestador)));}
 @Test void mensajeInvalidoNoGuarda(){var s=repo.guardar(servicio(EstadoServicio.CONTRATADO,true));var u=new EnviarMensajeServicioService(repo);for(var contenido:Arrays.asList(null," ","a".repeat(2001))){assertThrows(ServicioOperacionException.class,()->u.ejecutar(new EnviarMensajeServicioCommand(s.id(),cliente,contenido)));}assertTrue(repo.porId(s.id()).orElseThrow().mensajes().isEmpty());}
 @Test void comunicacionTrasCierreConservaPoliticaActual(){for(var e:List.of(EstadoServicio.FINALIZADO,EstadoServicio.CANCELADO)){var s=repo.guardar(servicio(e,true));new EnviarMensajeServicioService(repo).ejecutar(new EnviarMensajeServicioCommand(s.id(),prestador,"Hola"));assertEquals(1,new ConsultarMensajesServicioService(repo).ejecutar(accion(s,cliente)).size());}}
 static class Repo implements ServicioRepository {
 final Map<UUID,ServicioContratado> datos=new HashMap<>();public Optional<ServicioContratado> porId(UUID id){return Optional.ofNullable(datos.get(id));}public Optional<ServicioContratado> porSolicitudId(UUID id){return datos.values().stream().filter(s->s.solicitudId().equals(id)).findFirst();}public List<ServicioContratado> porUsuario(UUID id){return datos.values().stream().filter(s->s.esParticipante(id)).toList();}public List<ServicioContratado> porUsuario(UUID id,int p,int t){return porUsuario(id);}public List<ServicioContratado> activosDeUsuario(UUID id){return porUsuario(id).stream().filter(ServicioContratado::activo).toList();}public ServicioContratado guardar(ServicioContratado s){datos.put(s.id(),s);return s;}}
 class Propuestas implements ConsultaGestionPropuestasPort {
 final Map<UUID,Propuesta> datos=new HashMap<>();public Optional<Propuesta> porId(UUID id){return Optional.ofNullable(datos.get(id));}public List<Propuesta> activasDeSolicitud(UUID id){return datos.values().stream().filter(p->p.solicitudId().equals(id)&&p.estado()==EstadoPropuesta.ACTIVA).toList();}public void marcarAceptada(UUID id){datos.put(id,datos.get(id).aceptar(ahora));}public void cerrarActivasDeSolicitud(UUID id,UUID excepto){for(var p:activasDeSolicitud(id)){if(!p.id().equals(excepto))datos.put(p.id(),p.cerrar(ahora));}}}
 class Solicitudes implements ConsultaGestionSolicitudPort {Solicitud actual;public Optional<Solicitud> porId(UUID id){return Optional.ofNullable(actual).filter(s->s.id().equals(id));}public void marcarContratada(UUID id){actual=actual.transitarA(EstadoSolicitud.CONTRATADA,ahora);}}
}
